let browserStorage;try{browserStorage=window.localStorage}catch{}
let state=SaathState.load(browserStorage);
function storageWarning(){const el=document.querySelector('#storage-warning');el.hidden=false;el.textContent='Changes could not be saved on this device. You can keep using the demo, but changes may be lost when you leave.'}
let page='home';const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const save=()=>{if(!SaathState.save(browserStorage,state))storageWarning()};function time(t){let [h,m]=t.split(':');return `${+h%12||12}:${m} ${+h>=12?'PM':'AM'}`}function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)}function modal(html){$('#modal').innerHTML=html+'<button class="secondary" onclick="document.querySelector(\'#modal\').close()">Close</button>';$('#modal').querySelector('h2').id='dialog-title';$('#modal').showModal()}function call(){modal(`<h2>Call ${esc(state.caregiver||'your caregiver')}</h2>${state.phone?`<a class="primary" href="tel:${esc(state.phone.replace(/[^+0-9]/g,''))}">Call now</a>`:'<p>Add a caregiver phone number in Caregiver view to enable calling.</p>'}`)}function activityRows(edit=false){return state.activities.map(a=>`<div class="row"><div class="${a.done?'done':''}"><strong>${esc(a.title)}</strong><small>${time(a.time)} · ${esc(a.note)}</small></div><button class="${a.done?'secondary':'primary'}" onclick="complete(${a.id})">${a.done?'Undo':'✓ Done'}</button>${edit?`<button class="secondary" onclick="editActivity(${a.id})" aria-label="Edit ${esc(a.title)}">Edit</button><button class="secondary" onclick="removeActivity(${a.id})" aria-label="Remove ${esc(a.title)}">Remove</button>`:''}</div>`).join('')||'<p>No activities yet. Add one in Caregiver view.</p>'}function complete(id){state=SaathState.rollover(state);let a=state.activities.find(a=>a.id===id);if(!a)return;SaathState.toggle(state,id);save();render();toast(a.done?'All done. Take your time.':'Activity restored.')}function removeActivity(id){let a=state.activities.find(a=>a.id===id);if(!a)return;modal(`<h2>Remove this activity?</h2><p>${esc(a.title)}</p><button class="primary" onclick="confirmRemove(${id})">Remove activity</button>`)}
function editActivity(id) {
  const activity = state.activities.find(item => item.id === id);
  if (!activity) return;

  modal(`<h2>Edit activity</h2>
    <form id="edit-activity" class="form">
      <label>Activity<input name="title" required maxlength="80" value="${esc(activity.title)}"></label>
      <label>Time<input name="time" type="time" required value="${esc(activity.time)}"></label>
      <label>A helpful note<input name="note" maxlength="160" value="${esc(activity.note)}"></label>
      <button class="primary">Save changes</button>
    </form>`);

  $('#edit-activity').onsubmit = event => {
    event.preventDefault();
    const form = event.currentTarget;
    const titleInput = form.elements.namedItem('title');
    if (!titleInput.value.trim()) {
      titleInput.setCustomValidity('Enter an activity name.');
      titleInput.reportValidity();
      return;
    }

    if (!SaathState.editActivity(state, id, Object.fromEntries(new FormData(form)))) {
      $('#modal').close();
      render();
      toast('This activity is no longer available.');
      return;
    }

    save();
    $('#modal').close();
    render();
    $('#app').focus();
    toast('Activity updated');
  };
  $('#edit-activity input').oninput = event => event.target.setCustomValidity('');
}

function confirmRemove(id){state.activities=state.activities.filter(a=>a.id!==id);save();$('#modal').close();render();toast('Activity removed')}
function resetDemo(){modal('<h2>Reset the demo?</h2><p>This removes routines, details, memories and completion history saved in this browser, then restores the sample routines and clears the profile fields.</p><button class="primary" onclick="confirmReset()">Reset demo</button>')}
function confirmReset(){state=SaathState.defaults();save();$('#modal').close();go('home');toast('Demo reset')}
function go(p){page=p;render();window.scrollTo(0,0);$('#app').focus()}function render(){state=SaathState.rollover(state);document.body.dataset.view=page==='caregiver'?'caregiver':'person';document.querySelectorAll('nav button').forEach(b=>(b.classList.toggle('active',b.dataset.page===page),b.setAttribute('aria-current',b.dataset.page===page?'page':'false')));let a=state.activities.find(a=>!a.done),n=new Date(),hour=n.getHours();let greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';let html='';if(page==='home'){html=`<div class="intro"><div><div class="eyebrow">A LITTLE SUPPORT, EVERY DAY</div><h1>${greeting}${state.name?', '+esc(state.name):''}.</h1><p>Let’s take today one gentle step at a time.</p></div><div class="clock"><span class="clock-label">Current time</span><strong id="clock"></strong><span>${n.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span></div></div><div class="layout"><section class="next"><span class="pill">${a?'YOUR NEXT ACTIVITY':'TODAY’S ACTIVITIES COMPLETE'}</span><h2>${a?esc(a.title):'A little time for yourself'}</h2><p>${a?`${time(a.time)} · ${esc(a.note)}`:'You have finished your plan. Enjoy a quiet moment or revisit a favourite memory.'}</p><button class="primary" onclick="${a?`complete(${a.id})`:`go('memories')`}">${a?'✓  I’ve done this':'My memories'}</button><svg class="sprig" viewBox="0 0 150 230" fill="none" aria-hidden="true"><path d="M81 225C40 155 103 95 72 12" stroke="#879d6a" stroke-width="3"/><path d="M72 65C18 61 25 16 30 10c39 4 49 25 42 55ZM80 116c-3-45 39-55 55-53 5 37-22 56-55 53ZM66 164c-46 2-57-32-57-47 35-12 63 14 57 47ZM70 207c-3-39 40-56 59-51 4 39-28 53-59 51Z" fill="#a9b68d"/></svg></section><aside class="support"><h2>A familiar voice is close.</h2><p>Whenever you need a little help.</p><div class="person"><div class="avatar" aria-hidden="true">☀</div><div><strong>${esc(state.caregiver||'Your caregiver')}</strong><small>${esc(state.relationship)}</small></div></div><button class="secondary" onclick="call()">☎  Call my caregiver</button></aside></div><div class="section-title"><h2>Your familiar things</h2><span>Everything you need, right here.</span></div><div class="tiles"><button class="tile" onclick="go('plan')"><span class="icon">◷</span><span class="arrow">↗</span><strong>My reminders</strong><small>A simple plan for your day</small></button><button class="tile" onclick="go('people')"><span class="icon">♡</span><span class="arrow">↗</span><strong>My people</strong><small>The people who care about you</small></button><button class="tile" onclick="go('memories')"><span class="icon">▧</span><span class="arrow">↗</span><strong>My memories</strong><small>Little moments to smile about</small></button></div><div class="bottom"><span>❧  You’re doing well. There’s no rush.</span><span>Made for a little more peace of mind.</span></div>`}else if(page==='plan'){html=`<div class="eyebrow">ONE STEP AT A TIME</div><h1>My day</h1><p>Here is your plan for today.</p><section class="panel">${activityRows()}</section>`}else if(page==='people'){html=`<h1>My people</h1><p>A familiar person is just a call away.</p><div class="panel"><div class="person"><div class="avatar">☀</div><div><strong>${esc(state.caregiver||'Your caregiver')}</strong><small>${esc(state.relationship)}</small></div></div><button class="primary" onclick="call()">☎ Call ${esc(state.caregiver||'my caregiver')}</button></div>`}else if(page==='memories'){let memories=state.memories||[];html=`<div class="eyebrow">FAMILIAR MOMENTS</div><h1>My memories</h1><p>Enjoy these moments at your own pace.</p><div class="tiles">${memories.length?memories.map(m=>`<article class="memory"><span aria-hidden="true">❧</span><b>${esc(m.title)}</b><p>${esc(m.note)}</p></article>`).join(''):'<div class="panel" style="grid-column:1/-1"><h2>Your story belongs here.</h2><p>Your caregiver can add familiar places, favourite moments, and little stories in Caregiver view.</p></div>'}</div>`}else if(page==='help'){html=`<h1>We’re here to help.</h1><p>Take your time. You can go home or call someone familiar.</p><section class="panel"><h2>Speak to ${esc(state.caregiver||'your caregiver')}</h2><p>${esc(state.relationship)}</p><button class="primary" onclick="call()">☎ Call my caregiver</button> <button class="secondary" onclick="go('home')">⌂ Go home</button></section>`}else{html=`<div class="eyebrow">CAREGIVER SPACE</div><h1>A little care, thoughtfully planned.</h1><p>${state.name?`Personalise ${esc(state.name)}’s day.`:'Add demo details and plan your day.'}</p><p class="notice">Use fictional names and details. Changes are saved in this browser only. This view has no password protection or cross-device syncing.</p><section class="panel"><h2>Familiar details</h2><form id="profile" class="form"><label>Name<input name="name" maxlength="80" value="${esc(state.name)}"></label><label>Caregiver name<input name="caregiver" maxlength="80" value="${esc(state.caregiver)}"></label><label>Relationship<input name="relationship" maxlength="80" value="${esc(state.relationship)}"></label><label>Caregiver phone<input name="phone" type="tel" maxlength="40" placeholder="Add a phone number" value="${esc(state.phone)}"></label><button class="primary">Save details</button></form></section><div class="section-title"><h2>Today’s activities</h2><span>${state.activities.filter(a=>a.done).length} of ${state.activities.length} completed</span></div><section class="panel">${activityRows(true)}<form id="activity" class="form"><label>Activity<input name="title" placeholder="e.g. Take a garden walk" required maxlength="80"></label><label>Time<input type="time" name="time" required value="10:00"></label><label>A helpful note<input name="note" placeholder="Where or with whom?" maxlength="160"></label><button class="primary">+ Add activity</button></form></section><div class="section-title"><h2>Memory notes</h2></div><section class="panel"><form id="memory" class="form"><label>A familiar moment<input name="title" required placeholder="e.g. Our Sunday garden" maxlength="80"></label><label>A short story<input name="note" required placeholder="Add a warm, familiar detail" maxlength="220"></label><button class="primary">+ Add memory</button></form><p class="notice">${(state.memories||[]).length} memory notes added.</p>${memoryManager()}</section><div class="section-title"><h2>Completion history</h2></div><section class="panel"><p class="notice">Activity check-offs recorded by this demo, not independently verified. The latest 200 entries are retained on this device.</p>${historyRows()}</section>`}$('#app').innerHTML=html;tick();if($('#profile'))$('#profile').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target);['name','caregiver','relationship','phone'].forEach(k=>state[k]=d.get(k).trim());save();render();toast('Details saved')};if($('#activity'))$('#activity').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target);if(!d.get('title').trim()){toast('Please enter an activity.');return}state.activities.push({id:Date.now(),title:d.get('title').trim(),time:d.get('time'),note:d.get('note').trim(),done:false});state.activities.sort((a,b)=>a.time.localeCompare(b.time));save();render();toast('Activity added')};if($('#memory'))$('#memory').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target);if(!d.get('title').trim()||!d.get('note').trim()){toast('Please add a title and a short story.');return}(state.memories||=[]).push({title:d.get('title').trim(),note:d.get('note').trim()});save();render();toast('Memory added')}}function tick(){if($('#clock'))$('#clock').textContent=new Date().toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}document.querySelector('#reset-demo').onclick=resetDemo;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));render();setInterval(tick,1000);

function historyRows(){return state.history.length?state.history.slice().reverse().map(h=>`<div class="history-entry"><strong>${esc(h.title)}</strong><small>${h.done?'Marked complete':'Completion undone'} · ${esc(new Date(h.at).toLocaleString('en-IN'))}</small></div>`).join(''):'<p>No completion history yet. Mark an activity done to see it here.</p>'}
function memoryManager(){return state.memories.map((m,i)=>`<div class="row"><div><strong>${esc(m.title)}</strong><small>${esc(m.note)}</small></div><button class="secondary" onclick="removeMemory(${i})" aria-label="Remove memory: ${esc(m.title)}">Remove</button></div>`).join('')}
function removeMemory(i){if(!state.memories[i])return;modal(`<h2>Remove this memory?</h2><p>${esc(state.memories[i].title)}</p><button class="primary" onclick="confirmRemoveMemory(${i})">Remove memory</button>`)}
function confirmRemoveMemory(i){state.memories.splice(i,1);save();$('#modal').close();render();toast('Memory removed')}
window.addEventListener('storage',e=>{if(e.key==='saath-v1'||e.key===null){if($('#modal').open)$('#modal').close();state=SaathState.load(browserStorage);render();toast('Updated from another tab on this device.')}});
setInterval(()=>{const date=state.date;state=SaathState.rollover(state);if(date!==state.date){save();render()}},30000);

if(!browserStorage)storageWarning();
